// Each question is asked to both engines. DataForSEO limits prompts to 500 characters.
const settings = $('Your brand').first().json;
const engines = [
  { engine: 'ChatGPT', path: 'chat_gpt', task: { model_name: 'gpt-4o-mini', web_search: true, force_web_search: true } },
  { engine: 'Perplexity', path: 'perplexity', task: { model_name: 'sonar' } },
];
const out = [];
for (const { json } of $input.all()) {
  const question = String(json.question || '').trim().slice(0, 500);
  if (!question) continue;
  for (const e of engines) {
    out.push({
      json: {
        question,
        engine: e.engine,
        enginePath: e.path,
        task: {
          ...e.task,
          user_prompt: question,
          max_output_tokens: 1024,
          web_search_country_iso_code: settings.country,
          tag: 'brand-monitor',
        },
      },
    });
  }
}
return out;

const settings = $('Your brand').first().json;
const list = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean);
const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const countNames = (text, names) => names.reduce((n, name) =>
  n + (text.match(new RegExp('(^|[^\\p{L}\\p{N}])' + escape(name) + '(?=$|[^\\p{L}\\p{N}])', 'giu')) || []).length, 0);
const host = (u) => { try { return new URL(u).hostname.replace(/^www\./, '').toLowerCase(); } catch { return ''; } };
const domain = settings.domain.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '').toLowerCase();
const brandNames = list(settings.brandNames);
const competitors = list(settings.competitors);
const week = new Date().toISOString().slice(0, 10);

return $input.all().map((item, i) => {
  const req = $('One request per engine').itemMatching(i).json;
  const task = item.json.tasks?.[0];
  const result = task?.result?.[0];
  if (!result || task.status_code !== 20000) {
    return { json: { week, engine: req.engine, question: req.question, status: 'error: ' + (task?.status_message || item.json.status_message || item.json.error?.message || 'no result'),
      brand_mentioned: false, brand_mentions: 0, domain_cited: false, our_cited_urls: '', sources: 0, top_sources: '', competitor_mentions: '', cost_usd: task?.cost || 0, answer: '' } };
  }
  const sections = (result.items || []).flatMap((it) => it.sections || []);
  const answer = sections.map((s) => s.text || '').join('\n').trim();
  const urls = [...new Set(sections.flatMap((s) => (s.annotations || []).map((a) => a.url)).filter(Boolean))];
  const ours = urls.filter((u) => { const h = host(u); return h === domain || h.endsWith('.' + domain); });
  const mentions = countNames(answer, brandNames);
  const compText = competitors.map((c) => `${c}: ${countNames(answer, [c])}`).join(', ');
  return {
    json: {
      week,
      engine: req.engine,
      question: req.question,
      status: 'ok',
      brand_mentioned: mentions > 0,
      brand_mentions: mentions,
      domain_cited: ours.length > 0,
      our_cited_urls: ours.join(' '),
      sources: urls.length,
      top_sources: [...new Set(urls.map(host))].slice(0, 8).join(', '),
      competitor_mentions: compText,
      cost_usd: task.cost || 0,
      answer: answer.slice(0, 5000),
    },
  };
});

const rows = $input.all().map((i) => i.json);
const settings = $('Your brand').first().json;
const domain = settings.domain.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');
const lines = ['ChatGPT', 'Perplexity'].map((engine) => {
  const r = rows.filter((x) => x.engine === engine && x.status === 'ok');
  const named = r.filter((x) => x.brand_mentioned).length;
  const cited = r.filter((x) => x.domain_cited).length;
  return `*${engine}*: named in ${named}/${r.length} answers, ${domain} cited in ${cited}/${r.length}`;
});
const missed = rows.filter((x) => x.status === 'ok' && !x.brand_mentioned).map((x) => `- ${x.engine}: ${x.question}`).slice(0, 10);
const errors = rows.filter((x) => x.status !== 'ok').length;
const cost = rows.reduce((s, x) => s + (Number(x.cost_usd) || 0), 0);
const text = [
  `:mag: *AI visibility for ${list(settings.brandNames)[0]}, week of ${rows[0]?.week || ''}*`,
  ...lines,
  missed.length ? '\nQuestions where you were not named:\n' + missed.join('\n') : '\nNamed in every answer this week.',
  errors ? `\n${errors} request(s) failed, see the status column in the sheet.` : '',
  `\nDataForSEO cost this run: $${cost.toFixed(3)}`,
].join('\n');
function list(s) { return String(s || '').split(',').map((x) => x.trim()).filter(Boolean); }
return [{ json: { text } }];
